import { BufferReader } from './buffer-reader'

const TOTAL_BATCHES = 1000
const OPERATIONS_PER_BATCH = 1000

if (
  !Number.isInteger(TOTAL_BATCHES) ||
  TOTAL_BATCHES <= 0 ||
  !Number.isInteger(OPERATIONS_PER_BATCH) ||
  OPERATIONS_PER_BATCH <= 0
) {
  throw new Error('Benchmark constants must be positive integers')
}

let batchIndex = 0
const startTime = performance.now()

const reader = new BufferReader()
const buffer = Buffer.from([33, 33, 33, 33, 33, 33, 33, 0])

const runBatch = () => {
  if (batchIndex >= TOTAL_BATCHES) {
    console.log(performance.now() - startTime)
    return
  }

  for (let operationIndex = 0; operationIndex < OPERATIONS_PER_BATCH; operationIndex++) {
    reader.setBuffer(0, buffer)
    reader.cstring()
  }

  batchIndex++
  setImmediate(runBatch)
}

runBatch()